  "code": "\n  (function () {\n    if (window.__snzRibbonReady) return;\n    window.__snzRibbonReady = true;\n    // the ribbon's top edge sits exactly on its section's top edge (folds on the orange, nothing hanging into the white above)\n    var overlap = function () { return 0; };\n    function place() {\n      var all = document.querySelectorAll('.snz-ribbon');\n      for (var i = 0; i < all.length; i++) {\n        var el = all[i]; var sec = el.closest('.c-section'); if (!sec) continue;\n        var r = el.getBoundingClientRect(); if (!r.width) continue;\n        var current = parseFloat(el.style.getPropertyValue('--snz-ribbon-shift')) || 0;\n        var natural = r.top - current;\n        var shift = Math.round(sec.getBoundingClientRect().top - overlap() - natural);\n        if (shift !== current) el.style.setProperty('--snz-ribbon-shift', shift + 'px');\n      }\n    }\n    var t = null; function queue() { if (t) return; t = setTimeout(function () { t = null; place(); }, 80); }\n    place(); window.addEventListener('resize', queue); window.addEventListener('load', queue);\n    if ('MutationObserver' in window) new MutationObserver(queue).observe(document.body, { childList: true, subtree: true });\n    if ('ResizeObserver' in window) { var ro = new ResizeObserver(queue); ro.observe(document.body); var secs = document.querySelectorAll('.snz-ribbon'); for (var j = 0; j < secs.length; j++) { var sc = secs[j].closest('.c-section'); if (sc) ro.observe(sc); } }\n    setTimeout(queue, 1500); setTimeout(queue, 4000);\n    if (document.fonts && document.fonts.ready) document.fonts.ready.then(queue);\n  })();\n"
